import type { Metadata } from "next";
import { site } from "@/content/site";
import { filled } from "./placeholder";

export const siteTitle = filled(site.name) ?? "Portfolio & Résumé";

// Generated by src/app/opengraph-image.tsx. Listed explicitly because a page
// that sets its own `openGraph` replaces the inherited one.
const shareImage = { url: "/opengraph-image", width: 1200, height: 630 };

/** Builds page metadata with consistent canonical + Open Graph tags. */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title: `${title} · ${siteTitle}`,
      description,
      url: path,
      type: "website",
      siteName: siteTitle,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} · ${siteTitle}`,
      description,
      images: [shareImage.url],
    },
  };
}
